from django.db import migrations


def copy_meaning_to_senses(apps, schema_editor):
    Word = apps.get_model('vocab', 'Word')
    Sense = apps.get_model('vocab', 'Sense')

    for word in Word.objects.all():
        meaning = word.meaning.strip()
        if not meaning or Sense.objects.filter(word=word).exists():
            continue
        Sense.objects.create(word=word, part_of_speech='other', meaning=meaning, order=0)


